-- =====================================================================
-- Borrow Buddy · Migration 1 of 4 · Tables
-- ---------------------------------------------------------------------
-- Creates the 8 tables, their relationships (foreign keys), rules that
-- keep data valid (constraints), and indexes that make searches fast.
-- Security rules come in migration 2; workflow logic in migration 3.
-- =====================================================================

-- btree_gist lets one constraint compare both an item id (=) and a date
-- range (overlaps). We use it to stop double-booking an item.
create extension if not exists btree_gist with schema extensions;

-- ---------------------------------------------------------------------
-- Enum types: fixed lists of allowed values (must match src/lib/constants.ts)
-- ---------------------------------------------------------------------
create type public.item_category as enum (
  'electronics', 'books', 'tools', 'sports_outdoors', 'kitchen',
  'home_garden', 'clothing', 'toys_games', 'other'
);

create type public.item_condition as enum ('new', 'like_new', 'good', 'fair');

-- A listing's own status, set by the lender (or a moderator).
-- "On loan" is not stored here; it's worked out from active borrowings.
create type public.listing_status as enum ('active', 'paused', 'removed');

-- A request's life: pending -> approved | rejected | cancelled
create type public.request_status as enum ('pending', 'approved', 'rejected', 'cancelled');

-- A loan's life: active -> returned -> completed (or cancelled before pickup)
create type public.borrowing_status as enum ('active', 'returned', 'completed', 'cancelled');

create type public.notification_type as enum (
  'request_received', 'request_approved', 'request_rejected', 'request_cancelled',
  'borrowing_reminder', 'item_returned', 'borrowing_completed', 'review_received'
);

create type public.report_kind as enum ('question', 'item', 'user', 'bug', 'safety');
create type public.report_status as enum ('open', 'reviewing', 'resolved');

-- ---------------------------------------------------------------------
-- Shared trigger: keeps updated_at current on every UPDATE
-- ---------------------------------------------------------------------
create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- ---------------------------------------------------------------------
-- 1. profiles: public information about each member.
--    One row per Supabase Auth user. Email and password stay in Supabase
--    Auth (auth.users), which is never readable by the public.
-- ---------------------------------------------------------------------
create table public.profiles (
  id            uuid primary key references auth.users (id) on delete cascade,
  display_name  text not null check (char_length(display_name) between 2 and 60),
  bio           text check (char_length(bio) <= 500),
  area          text check (char_length(area) <= 60),   -- general area only
  avatar_path   text,                                   -- path in the "avatars" bucket
  is_moderator  boolean not null default false,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create trigger profiles_updated_at before update on public.profiles
  for each row execute function public.set_updated_at();

-- Create a profile automatically when someone signs up.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  name text := coalesce(
    nullif(trim(new.raw_user_meta_data ->> 'display_name'), ''),
    nullif(split_part(new.email, '@', 1), ''),
    'Member'
  );
begin
  -- Names must be 2–60 characters: pad very short ones, cut long ones.
  if char_length(name) < 2 then
    name := rpad(name, 2, '_');
  end if;

  insert into public.profiles (id, display_name, area)
  values (
    new.id,
    left(name, 60),
    nullif(left(trim(new.raw_user_meta_data ->> 'area'), 60), '')
  );
  return new;
end;
$$;

create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---------------------------------------------------------------------
-- 2. items: things people lend
-- ---------------------------------------------------------------------
create table public.items (
  id            uuid primary key default gen_random_uuid(),
  lender_id     uuid not null references public.profiles (id) on delete cascade,
  title         text not null check (char_length(title) between 3 and 100),
  description   text not null check (char_length(description) between 10 and 2000),
  category      public.item_category not null,
  condition     public.item_condition not null,
  area          text not null check (char_length(area) between 2 and 60),
  status        public.listing_status not null default 'active',
  max_days      integer check (max_days between 1 and 365),
  instructions  text check (char_length(instructions) <= 1000),
  is_sample     boolean not null default false,
  -- Full-text search column, updated automatically by Postgres.
  search        tsvector generated always as (
                  setweight(to_tsvector('english', coalesce(title, '')), 'A') ||
                  setweight(to_tsvector('english', coalesce(description, '')), 'B')
                ) stored,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create index items_lender_idx   on public.items (lender_id);
create index items_browse_idx   on public.items (status, category, created_at desc);
create index items_area_idx     on public.items (area);
create index items_search_idx   on public.items using gin (search);

create trigger items_updated_at before update on public.items
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------
-- 3. item_images: photos for each item (files live in Storage)
-- ---------------------------------------------------------------------
create table public.item_images (
  id            uuid primary key default gen_random_uuid(),
  item_id       uuid not null references public.items (id) on delete cascade,
  storage_path  text not null unique,           -- e.g. "<user id>/<item id>/<file>.jpg"
  position      smallint not null default 0 check (position between 0 and 9),
  created_at    timestamptz not null default now()
);

create index item_images_item_idx on public.item_images (item_id, position);

-- ---------------------------------------------------------------------
-- 4. borrowing_requests: "can I borrow this from <date> to <date>?"
-- ---------------------------------------------------------------------
create table public.borrowing_requests (
  id            uuid primary key default gen_random_uuid(),
  item_id       uuid not null references public.items (id) on delete cascade,
  borrower_id   uuid not null references public.profiles (id) on delete cascade,
  lender_id     uuid not null references public.profiles (id) on delete cascade,
  start_date    date not null,
  end_date      date not null,
  message       text check (char_length(message) <= 1000),
  status        public.request_status not null default 'pending',
  decided_at    timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  constraint request_dates_valid check (end_date >= start_date),
  constraint request_not_own_item check (borrower_id <> lender_id)
);

create index requests_borrower_idx on public.borrowing_requests (borrower_id, created_at desc);
create index requests_lender_idx   on public.borrowing_requests (lender_id, status, created_at desc);
create index requests_item_idx     on public.borrowing_requests (item_id, status);

-- A borrower can't have two pending requests for the same item at once.
create unique index requests_one_pending_per_item
  on public.borrowing_requests (item_id, borrower_id) where status = 'pending';

create trigger requests_updated_at before update on public.borrowing_requests
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------
-- 5. borrowings: an approved request becomes a loan
-- ---------------------------------------------------------------------
create table public.borrowings (
  id                     uuid primary key default gen_random_uuid(),
  request_id             uuid not null unique references public.borrowing_requests (id) on delete cascade,
  item_id                uuid not null references public.items (id) on delete cascade,
  borrower_id            uuid not null references public.profiles (id) on delete cascade,
  lender_id              uuid not null references public.profiles (id) on delete cascade,
  start_date             date not null,
  end_date               date not null,
  status                 public.borrowing_status not null default 'active',
  pickup_details         text check (char_length(pickup_details) <= 1000), -- visible to both parties only
  returned_at            timestamptz,
  lender_confirmed_at    timestamptz,
  borrower_confirmed_at  timestamptz,
  reminder_sent_at       timestamptz,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  constraint borrowing_dates_valid check (end_date >= start_date),
  -- THE double-booking guard: two active loans of the same item can never
  -- have overlapping dates. Postgres itself refuses, even if app code has a bug.
  constraint borrowings_no_overlap exclude using gist (
    item_id with =,
    daterange(start_date, end_date, '[]') with &&
  ) where (status = 'active')
);

create index borrowings_borrower_idx on public.borrowings (borrower_id, status);
create index borrowings_lender_idx   on public.borrowings (lender_id, status);
create index borrowings_due_idx      on public.borrowings (end_date) where status = 'active';

create trigger borrowings_updated_at before update on public.borrowings
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------
-- 6. notifications: in-app messages for one user
-- ---------------------------------------------------------------------
create table public.notifications (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references public.profiles (id) on delete cascade,
  type          public.notification_type not null,
  title         text not null,
  body          text,
  link          text,             -- where clicking it takes you, e.g. /dashboard/requests
  read_at       timestamptz,
  created_at    timestamptz not null default now()
);

create index notifications_user_idx on public.notifications (user_id, created_at desc);
create index notifications_unread_idx on public.notifications (user_id) where read_at is null;

-- ---------------------------------------------------------------------
-- 7. reviews: after a completed loan, each side can review the other once
-- ---------------------------------------------------------------------
create table public.reviews (
  id            uuid primary key default gen_random_uuid(),
  borrowing_id  uuid not null references public.borrowings (id) on delete cascade,
  reviewer_id   uuid not null references public.profiles (id) on delete cascade,
  reviewee_id   uuid not null references public.profiles (id) on delete cascade,
  rating        smallint not null check (rating between 1 and 5),
  comment       text check (char_length(comment) <= 1000),
  created_at    timestamptz not null default now(),
  constraint review_once unique (borrowing_id, reviewer_id),
  constraint review_not_self check (reviewer_id <> reviewee_id)
);

create index reviews_reviewee_idx on public.reviews (reviewee_id, created_at desc);

-- ---------------------------------------------------------------------
-- 8. reports: contact messages and reports about items/members
-- ---------------------------------------------------------------------
create table public.reports (
  id               uuid primary key default gen_random_uuid(),
  reporter_id      uuid references public.profiles (id) on delete set null, -- null if not logged in
  reporter_name    text not null check (char_length(reporter_name) between 2 and 80),
  reporter_email   text not null check (char_length(reporter_email) between 3 and 200),
  kind             public.report_kind not null,
  item_id          uuid references public.items (id) on delete set null,
  reported_user_id uuid references public.profiles (id) on delete set null,
  reference        text check (char_length(reference) <= 200),
  message          text not null check (char_length(message) between 10 and 2000),
  status           public.report_status not null default 'open',
  moderator_note   text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

create index reports_status_idx on public.reports (status, created_at desc);

create trigger reports_updated_at before update on public.reports
  for each row execute function public.set_updated_at();

-- >>> 20261105120100_security.sql
-- =====================================================================
-- Borrow Buddy · Migration 2 of 4 · Security
-- ---------------------------------------------------------------------
-- Two layers protect every table:
--   1. GRANTs: which columns each role may touch at all.
--      "anon" = visitors who aren't logged in, "authenticated" = members.
--   2. ROW LEVEL SECURITY (RLS) policies: which ROWS each person may
--      see or change, e.g. "only your own notifications".
-- Postgres enforces both on every query, whatever the website code does.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Helper: is the current user a moderator?
-- SECURITY DEFINER lets it read profiles without triggering RLS loops.
-- ---------------------------------------------------------------------
create or replace function public.is_moderator()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select p.is_moderator from public.profiles p where p.id = (select auth.uid())),
    false
  );
$$;

-- Helper: has the current user borrowed (or been approved to borrow) this
-- item? Used by the items policy. It's a function because visitors who
-- aren't logged in have no access to the borrowings table at all.
create or replace function public.has_borrowed_item(p_item_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select (select auth.uid()) is not null and exists (
    select 1 from public.borrowings b
    where b.item_id = p_item_id and b.borrower_id = (select auth.uid())
  );
$$;

-- ---------------------------------------------------------------------
-- Layer 1: GRANTs. Start from nothing, then allow only what's needed.
-- Workflow changes (requests, loans, reviews) are NOT granted here at
-- all: they go through the checked functions in migration 3.
-- ---------------------------------------------------------------------
revoke all on all tables in schema public from anon, authenticated;

-- profiles: everyone may read public profile fields; members may edit
-- only these four columns (so nobody can make themselves a moderator).
grant select on public.profiles to anon, authenticated;
grant update (display_name, bio, area, avatar_path) on public.profiles to authenticated;

-- items
grant select on public.items to anon, authenticated;
grant insert (lender_id, title, description, category, condition, area, status, max_days, instructions)
  on public.items to authenticated;
grant update (title, description, category, condition, area, status, max_days, instructions)
  on public.items to authenticated;
grant delete on public.items to authenticated;

-- item_images
grant select on public.item_images to anon, authenticated;
grant insert (item_id, storage_path, position) on public.item_images to authenticated;
grant update (position) on public.item_images to authenticated;
grant delete on public.item_images to authenticated;

-- requests and loans: members can only READ (their own, see policies)
grant select on public.borrowing_requests to authenticated;
grant select on public.borrowings to authenticated;

-- notifications: read, mark as read, delete your own
grant select, delete on public.notifications to authenticated;
grant update (read_at) on public.notifications to authenticated;

-- reviews: public to read; written via submit_review()
grant select on public.reviews to anon, authenticated;

-- reports: anyone may send one; status/moderator_note can't be set by senders
grant insert (reporter_id, reporter_name, reporter_email, kind, item_id, reported_user_id, reference, message)
  on public.reports to anon, authenticated;
grant select on public.reports to authenticated;
grant update (status, moderator_note) on public.reports to authenticated;

-- ---------------------------------------------------------------------
-- Layer 2: Row Level Security policies
-- Note: "(select auth.uid())" is the logged-in user's id. Wrapping it in
-- a sub-select is a Supabase performance tip (evaluated once per query).
-- ---------------------------------------------------------------------
alter table public.profiles           enable row level security;
alter table public.items              enable row level security;
alter table public.item_images        enable row level security;
alter table public.borrowing_requests enable row level security;
alter table public.borrowings         enable row level security;
alter table public.notifications      enable row level security;
alter table public.reviews            enable row level security;
alter table public.reports            enable row level security;

-- profiles ------------------------------------------------------------
create policy "Profiles are public"
  on public.profiles for select to anon, authenticated
  using (true);

create policy "Members edit their own profile"
  on public.profiles for update to authenticated
  using (id = (select auth.uid()))
  with check (id = (select auth.uid()));

-- items ---------------------------------------------------------------
create policy "Active listings are public; owners and moderators see all of theirs"
  on public.items for select to anon, authenticated
  using (
    status = 'active'
    or lender_id = (select auth.uid())
    or (select public.is_moderator())
    -- people with a loan of a paused item can still open its page
    or public.has_borrowed_item(items.id)
  );

create policy "Members list items as themselves"
  on public.items for insert to authenticated
  with check (lender_id = (select auth.uid()));

create policy "Owners and moderators edit listings"
  on public.items for update to authenticated
  using (lender_id = (select auth.uid()) or (select public.is_moderator()))
  with check (lender_id = (select auth.uid()) or (select public.is_moderator()));

create policy "Owners delete their listings"
  on public.items for delete to authenticated
  using (lender_id = (select auth.uid()));

-- Extra rules for items that a policy can't express on its own:
--  * only moderators can set or undo "removed"
--  * a listing with a current or upcoming loan can't be deleted
create or replace function public.guard_items()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'UPDATE' then
    if (new.status = 'removed' or old.status = 'removed')
       and new.status is distinct from old.status
       and not public.is_moderator()
       and (select auth.uid()) is not null then
      raise exception 'Only moderators can remove or restore a listing.'
        using errcode = '42501';
    end if;
    return new;
  end if;

  -- DELETE
  if exists (
    select 1 from public.borrowings b
    where b.item_id = old.id and b.status in ('active', 'returned')
  ) then
    raise exception 'This item is on loan. Pause the listing instead, and delete it after the loan is completed.'
      using errcode = 'P0001';
  end if;
  return old;
end;
$$;

create trigger items_guard_update before update on public.items
  for each row execute function public.guard_items();
create trigger items_guard_delete before delete on public.items
  for each row execute function public.guard_items();

-- item_images -----------------------------------------------------------
create policy "Images are visible when their item is"
  on public.item_images for select to anon, authenticated
  using (exists (select 1 from public.items i where i.id = item_images.item_id));

create policy "Owners add images to their items, in their own folder"
  on public.item_images for insert to authenticated
  with check (
    exists (select 1 from public.items i where i.id = item_id and i.lender_id = (select auth.uid()))
    and storage_path like (select auth.uid())::text || '/%'
  );

create policy "Owners reorder images"
  on public.item_images for update to authenticated
  using (exists (select 1 from public.items i where i.id = item_id and i.lender_id = (select auth.uid())))
  with check (exists (select 1 from public.items i where i.id = item_id and i.lender_id = (select auth.uid())));

create policy "Owners delete images"
  on public.item_images for delete to authenticated
  using (exists (select 1 from public.items i where i.id = item_id and i.lender_id = (select auth.uid())));

-- borrowing_requests and borrowings: only the two people involved ---------
create policy "Borrower and lender see their requests"
  on public.borrowing_requests for select to authenticated
  using ((select auth.uid()) in (borrower_id, lender_id));

create policy "Borrower and lender see their loans"
  on public.borrowings for select to authenticated
  using ((select auth.uid()) in (borrower_id, lender_id));

-- notifications: strictly your own ----------------------------------------
create policy "Members see their own notifications"
  on public.notifications for select to authenticated
  using (user_id = (select auth.uid()));

create policy "Members mark their own notifications read"
  on public.notifications for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

create policy "Members delete their own notifications"
  on public.notifications for delete to authenticated
  using (user_id = (select auth.uid()));

-- reviews ---------------------------------------------------------------
create policy "Reviews are public"
  on public.reviews for select to anon, authenticated
  using (true);

-- reports ---------------------------------------------------------------
create policy "Anyone can send a report"
  on public.reports for insert to anon, authenticated
  with check (reporter_id is null or reporter_id = (select auth.uid()));

create policy "Senders see their reports; moderators see all"
  on public.reports for select to authenticated
  using (reporter_id = (select auth.uid()) or (select public.is_moderator()));

create policy "Moderators update reports"
  on public.reports for update to authenticated
  using ((select public.is_moderator()))
  with check ((select public.is_moderator()));

-- >>> 20261105120200_workflow.sql
-- =====================================================================
-- Borrow Buddy · Migration 3 of 4 · Borrowing workflow
-- ---------------------------------------------------------------------
-- Every step of a loan is a database function ("RPC") that the website
-- calls, e.g. supabase.rpc('approve_request', {...}). Each one:
--   * checks WHO is calling (only the lender can approve, etc.)
--   * checks the current STATE (you can't approve a cancelled request)
--   * makes all its changes at once (a transaction) and sends notifications
-- They run as SECURITY DEFINER (with the database's own rights), which is
-- why they check permissions themselves, very carefully, at the top.
-- Error messages are written for people, because the app shows them.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Internal helper: create a notification. Not callable by members.
-- ---------------------------------------------------------------------
create or replace function public.notify(
  p_user_id uuid,
  p_type public.notification_type,
  p_title text,
  p_body text default null,
  p_link text default null
)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.notifications (user_id, type, title, body, link)
  values (p_user_id, p_type, p_title, p_body, p_link);
$$;

-- Small helper: the logged-in user, or an error if nobody is logged in.
create or replace function public.require_user()
returns uuid
language plpgsql
stable
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
begin
  if uid is null then
    raise exception 'Log in to do this.' using errcode = '42501';
  end if;
  return uid;
end;
$$;

-- ---------------------------------------------------------------------
-- Step 1 · Borrower sends a request
-- ---------------------------------------------------------------------
create or replace function public.create_borrow_request(
  p_item_id uuid,
  p_start_date date,
  p_end_date date,
  p_message text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := public.require_user();
  v_item public.items;
  v_request_id uuid;
  v_days integer := p_end_date - p_start_date + 1;
begin
  select * into v_item from public.items where id = p_item_id;

  if v_item.id is null or v_item.status <> 'active' then
    raise exception 'This item isn''t available to borrow right now.';
  end if;
  if v_item.lender_id = uid then
    raise exception 'You can''t borrow your own item.';
  end if;
  if p_start_date is null or p_end_date is null or p_end_date < p_start_date then
    raise exception 'Choose a return date on or after the start date.';
  end if;
  if p_start_date < current_date then
    raise exception 'The start date can''t be in the past.';
  end if;
  if p_start_date > current_date + 180 then
    raise exception 'You can request dates up to 6 months ahead.';
  end if;
  if v_item.max_days is not null and v_days > v_item.max_days then
    raise exception 'The lender allows up to % days per loan. You asked for %.', v_item.max_days, v_days;
  end if;
  if char_length(p_message) > 1000 then
    raise exception 'Keep your message under 1,000 characters.';
  end if;
  if exists (
    select 1 from public.borrowings b
    where b.item_id = p_item_id and b.status = 'active'
      and daterange(b.start_date, b.end_date, '[]') && daterange(p_start_date, p_end_date, '[]')
  ) then
    raise exception 'The item is already booked for some of those dates. Choose different dates.';
  end if;

  begin
    insert into public.borrowing_requests (item_id, borrower_id, lender_id, start_date, end_date, message)
    values (p_item_id, uid, v_item.lender_id, p_start_date, p_end_date, nullif(trim(p_message), ''))
    returning id into v_request_id;
  exception when unique_violation then
    raise exception 'You already have a pending request for this item. Cancel it first to ask for new dates.';
  end;

  perform public.notify(
    v_item.lender_id, 'request_received',
    'New request for ' || v_item.title,
    (select display_name from public.profiles where id = uid)
      || ' wants to borrow it ' || to_char(p_start_date, 'FMDD Mon') || ' – ' || to_char(p_end_date, 'FMDD Mon') || '.',
    '/dashboard/requests'
  );
  return v_request_id;
end;
$$;

-- ---------------------------------------------------------------------
-- Step 2a · Lender approves → the request becomes an active loan
-- ---------------------------------------------------------------------
create or replace function public.approve_request(
  p_request_id uuid,
  p_pickup_details text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := public.require_user();
  r public.borrowing_requests;
  v_title text;
  v_borrowing_id uuid;
  other record;
begin
  -- "for update" locks the row so two clicks can't approve it twice.
  select * into r from public.borrowing_requests where id = p_request_id for update;

  if r.id is null or r.lender_id <> uid then
    raise exception 'Request not found.';
  end if;
  if r.status <> 'pending' then
    raise exception 'This request has already been %.', r.status;
  end if;
  if r.end_date < current_date then
    raise exception 'These dates have passed. Decline the request instead.';
  end if;
  if char_length(p_pickup_details) > 1000 then
    raise exception 'Keep the pickup details under 1,000 characters.';
  end if;

  select title into v_title from public.items where id = r.item_id;

  begin
    insert into public.borrowings (request_id, item_id, borrower_id, lender_id, start_date, end_date, pickup_details)
    values (r.id, r.item_id, r.borrower_id, r.lender_id, r.start_date, r.end_date, nullif(trim(p_pickup_details), ''))
    returning id into v_borrowing_id;
  exception when exclusion_violation then
    -- the double-booking guard from migration 1
    raise exception 'You''ve already approved another loan of this item for some of these dates.';
  end;

  update public.borrowing_requests
     set status = 'approved', decided_at = now()
   where id = r.id;

  perform public.notify(
    r.borrower_id, 'request_approved',
    'Request approved: ' || v_title,
    'You can pick it up from ' || to_char(r.start_date, 'FMDD Mon') || '. Return it by ' || to_char(r.end_date, 'FMDD Mon') || '.',
    '/dashboard/borrowing'
  );

  -- Other pending requests for overlapping dates can't be approved any
  -- more, so decline them automatically and tell those borrowers.
  for other in
    update public.borrowing_requests
       set status = 'rejected', decided_at = now()
     where item_id = r.item_id and status = 'pending' and id <> r.id
       and daterange(start_date, end_date, '[]') && daterange(r.start_date, r.end_date, '[]')
    returning borrower_id
  loop
    perform public.notify(
      other.borrower_id, 'request_rejected',
      'Request declined: ' || v_title,
      'Someone else is borrowing it on those dates. Try different dates.',
      '/dashboard/requests'
    );
  end loop;

  return v_borrowing_id;
end;
$$;

-- ---------------------------------------------------------------------
-- Step 2b · Lender declines
-- ---------------------------------------------------------------------
create or replace function public.reject_request(p_request_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := public.require_user();
  r public.borrowing_requests;
begin
  select * into r from public.borrowing_requests where id = p_request_id for update;
  if r.id is null or r.lender_id <> uid then
    raise exception 'Request not found.';
  end if;
  if r.status <> 'pending' then
    raise exception 'This request has already been %.', r.status;
  end if;

  update public.borrowing_requests set status = 'rejected', decided_at = now() where id = r.id;

  perform public.notify(
    r.borrower_id, 'request_rejected',
    'Request declined: ' || (select title from public.items where id = r.item_id),
    'The lender can''t lend it on those dates.',
    '/dashboard/requests'
  );
end;
$$;

-- ---------------------------------------------------------------------
-- Step 2c · Borrower cancels a pending request
-- ---------------------------------------------------------------------
create or replace function public.cancel_request(p_request_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := public.require_user();
  r public.borrowing_requests;
begin
  select * into r from public.borrowing_requests where id = p_request_id for update;
  if r.id is null or r.borrower_id <> uid then
    raise exception 'Request not found.';
  end if;
  if r.status <> 'pending' then
    raise exception 'Only pending requests can be cancelled. This one has been %.', r.status;
  end if;

  update public.borrowing_requests set status = 'cancelled', decided_at = now() where id = r.id;

  perform public.notify(
    r.lender_id, 'request_cancelled',
    'Request cancelled: ' || (select title from public.items where id = r.item_id),
    (select display_name from public.profiles where id = uid) || ' cancelled their request.',
    '/dashboard/requests'
  );
end;
$$;

-- ---------------------------------------------------------------------
-- Either side cancels an approved loan before it starts
-- ---------------------------------------------------------------------
create or replace function public.cancel_borrowing(p_borrowing_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := public.require_user();
  b public.borrowings;
  v_other uuid;
begin
  select * into b from public.borrowings where id = p_borrowing_id for update;
  if b.id is null or uid not in (b.borrower_id, b.lender_id) then
    raise exception 'Loan not found.';
  end if;
  if b.status <> 'active' or b.start_date <= current_date then
    raise exception 'Only loans that haven''t started yet can be cancelled.';
  end if;

  update public.borrowings set status = 'cancelled' where id = b.id;
  update public.borrowing_requests set status = 'cancelled' where id = b.request_id;

  v_other := case when uid = b.borrower_id then b.lender_id else b.borrower_id end;
  perform public.notify(
    v_other, 'request_cancelled',
    'Loan cancelled: ' || (select title from public.items where id = b.item_id),
    (select display_name from public.profiles where id = uid) || ' cancelled the loan before it started.',
    '/dashboard'
  );
end;
$$;

-- ---------------------------------------------------------------------
-- Step 3 · Return and completion
-- The first person to confirm marks the item "returned"; when the other
-- person confirms too, the loan is "completed" and both can leave reviews.
-- ---------------------------------------------------------------------
create or replace function public.confirm_return(p_borrowing_id uuid)
returns public.borrowing_status
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := public.require_user();
  b public.borrowings;
  v_title text;
  v_is_lender boolean;
  v_other uuid;
begin
  select * into b from public.borrowings where id = p_borrowing_id for update;
  if b.id is null or uid not in (b.borrower_id, b.lender_id) then
    raise exception 'Loan not found.';
  end if;
  if b.status not in ('active', 'returned') then
    raise exception 'This loan is already %.', b.status;
  end if;
  if b.status = 'active' and b.start_date > current_date then
    raise exception 'This loan hasn''t started yet.';
  end if;

  v_is_lender := uid = b.lender_id;
  v_other := case when v_is_lender then b.borrower_id else b.lender_id end;
  select title into v_title from public.items where id = b.item_id;

  if (v_is_lender and b.lender_confirmed_at is not null)
     or (not v_is_lender and b.borrower_confirmed_at is not null) then
    raise exception 'You''ve already confirmed this return. Waiting for the other person.';
  end if;

  update public.borrowings
     set lender_confirmed_at   = case when v_is_lender then now() else lender_confirmed_at end,
         borrower_confirmed_at = case when not v_is_lender then now() else borrower_confirmed_at end,
         returned_at           = coalesce(returned_at, now()),
         status                = 'returned'
   where id = b.id
   returning * into b;

  if b.lender_confirmed_at is not null and b.borrower_confirmed_at is not null then
    update public.borrowings set status = 'completed' where id = b.id;
    perform public.notify(b.lender_id, 'borrowing_completed', 'Loan completed: ' || v_title,
      'Thanks for lending! You can now review the borrower.', '/dashboard/history');
    perform public.notify(b.borrower_id, 'borrowing_completed', 'Loan completed: ' || v_title,
      'Thanks for returning it! You can now review the lender.', '/dashboard/history');
    return 'completed';
  end if;

  perform public.notify(
    v_other, 'item_returned',
    'Confirm the return: ' || v_title,
    case when v_is_lender
      then 'The lender marked the item as returned. Please confirm to complete the loan.'
      else 'The borrower says they returned it. Please confirm you got it back.' end,
    case when v_is_lender then '/dashboard/borrowing' else '/dashboard/lending' end
  );
  return 'returned';
end;
$$;

-- ---------------------------------------------------------------------
-- Reviews: one per person per completed loan
-- ---------------------------------------------------------------------
create or replace function public.submit_review(
  p_borrowing_id uuid,
  p_rating smallint,
  p_comment text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := public.require_user();
  b public.borrowings;
  v_reviewee uuid;
  v_id uuid;
begin
  select * into b from public.borrowings where id = p_borrowing_id;
  if b.id is null or uid not in (b.borrower_id, b.lender_id) then
    raise exception 'Loan not found.';
  end if;
  if b.status <> 'completed' then
    raise exception 'You can leave a review once both of you have confirmed the return.';
  end if;
  if p_rating is null or p_rating not between 1 and 5 then
    raise exception 'Choose a rating from 1 to 5 stars.';
  end if;
  if char_length(p_comment) > 1000 then
    raise exception 'Keep your review under 1,000 characters.';
  end if;

  v_reviewee := case when uid = b.lender_id then b.borrower_id else b.lender_id end;

  begin
    insert into public.reviews (borrowing_id, reviewer_id, reviewee_id, rating, comment)
    values (b.id, uid, v_reviewee, p_rating, nullif(trim(p_comment), ''))
    returning id into v_id;
  exception when unique_violation then
    raise exception 'You''ve already reviewed this loan.';
  end;

  perform public.notify(v_reviewee, 'review_received', 'You received a review',
    (select display_name from public.profiles where id = uid) || ' gave you ' || p_rating || ' out of 5.',
    '/dashboard/profile');
  return v_id;
end;
$$;

-- ---------------------------------------------------------------------
-- Public read helpers. They reveal only dates and counts, never who is
-- borrowing what, so it's safe for anyone to call them.
-- ---------------------------------------------------------------------

-- Dates an item is already booked (for the date picker)
create or replace function public.item_booked_ranges(p_item_id uuid)
returns table (start_date date, end_date date)
language sql
stable
security definer
set search_path = ''
as $$
  select b.start_date, b.end_date
  from public.borrowings b
  where b.item_id = p_item_id and b.status = 'active' and b.end_date >= current_date
  order by b.start_date;
$$;

-- Which of these items are on loan today, and when they're due back
create or replace function public.items_on_loan(p_item_ids uuid[])
returns table (item_id uuid, due_back date)
language sql
stable
security definer
set search_path = ''
as $$
  select b.item_id, b.end_date
  from public.borrowings b
  where b.item_id = any (p_item_ids) and b.status = 'active'
    and current_date between b.start_date and b.end_date;
$$;

-- Numbers shown on a public profile
create or replace function public.profile_stats(p_user_id uuid)
returns table (
  items_listed integer,
  items_borrowed integer,
  lends_completed integer,
  review_count integer,
  average_rating numeric
)
language sql
stable
security definer
set search_path = ''
as $$
  select
    (select count(*)::int from public.items i where i.lender_id = p_user_id and i.status = 'active'),
    (select count(*)::int from public.borrowings b where b.borrower_id = p_user_id and b.status = 'completed'),
    (select count(*)::int from public.borrowings b where b.lender_id = p_user_id and b.status = 'completed'),
    (select count(*)::int from public.reviews r where r.reviewee_id = p_user_id),
    (select round(avg(r.rating), 1) from public.reviews r where r.reviewee_id = p_user_id);
$$;

-- ---------------------------------------------------------------------
-- Reminders: notify borrowers the day before an item is due back.
-- Run once a day by a scheduler (see supabase/optional/schedule_reminders.sql).
-- ---------------------------------------------------------------------
create or replace function public.send_due_reminders()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  b record;
  n integer := 0;
begin
  for b in
    update public.borrowings
       set reminder_sent_at = now()
     where status = 'active' and reminder_sent_at is null
       and end_date = current_date + 1
    returning id, borrower_id, item_id, end_date
  loop
    perform public.notify(
      b.borrower_id, 'borrowing_reminder',
      'Due back tomorrow: ' || (select title from public.items where id = b.item_id),
      'Please return it by ' || to_char(b.end_date, 'FMDD Mon') || '.',
      '/dashboard/borrowing'
    );
    n := n + 1;
  end loop;
  return n;
end;
$$;

-- ---------------------------------------------------------------------
-- Who may call which function
-- ---------------------------------------------------------------------
revoke execute on all functions in schema public from public, anon, authenticated;

grant execute on function
  public.create_borrow_request(uuid, date, date, text),
  public.approve_request(uuid, text),
  public.reject_request(uuid),
  public.cancel_request(uuid),
  public.cancel_borrowing(uuid),
  public.confirm_return(uuid),
  public.submit_review(uuid, smallint, text)
to authenticated;

grant execute on function
  public.item_booked_ranges(uuid),
  public.items_on_loan(uuid[]),
  public.profile_stats(uuid),
  public.is_moderator(),
  public.has_borrowed_item(uuid)
to anon, authenticated;

-- require_user() is used inside the functions above (it only reads auth.uid())
grant execute on function public.require_user() to authenticated;

-- notify() and send_due_reminders() stay private: members can't call them.

-- >>> 20261105120300_storage.sql
-- =====================================================================
-- Borrow Buddy · Migration 4 of 4 · Photo storage
-- ---------------------------------------------------------------------
-- Two "buckets" (folders in Supabase Storage):
--   item-images  photos of listed items
--   avatars      profile photos
-- Both are publicly readable (so <img> tags just work), but people can
-- only upload into, change or delete files in a folder named after their
-- own user id: "<user id>/…". Size and file type are limited too.
-- =====================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('item-images', 'item-images', true, 5242880, array['image/jpeg', 'image/png', 'image/webp']),
  ('avatars',     'avatars',     true, 2097152, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- (storage.foldername(name))[1] is the first folder in the file's path.
create policy "Members upload to their own folder"
  on storage.objects for insert to authenticated
  with check (
    bucket_id in ('item-images', 'avatars')
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

create policy "Members replace their own files"
  on storage.objects for update to authenticated
  using (
    bucket_id in ('item-images', 'avatars')
    and (storage.foldername(name))[1] = (select auth.uid())::text
  )
  with check (
    bucket_id in ('item-images', 'avatars')
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

create policy "Members delete their own files"
  on storage.objects for delete to authenticated
  using (
    bucket_id in ('item-images', 'avatars')
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );
